'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const source=fs.readFileSync(path.join(__dirname,'app.js'),'utf8'),css=fs.readFileSync(path.join(__dirname,'style.css'),'utf8');
const start=source.indexOf('const homeOptions='),end=source.indexOf('const defaults=',start);
assert.ok(start>=0&&end>start);
const {normaliseHome:n,homeClockParts:c,homeOptions:o}=new Function(source.slice(start,end)+';return {normaliseHome,homeClockParts,homeOptions};')();
assert.deepEqual(n(),{homeLayout:'classic',homeClock:'thin',homeWallpaper:'abstract'});
assert.deepEqual(n({homeLayout:'bad',homeClock:null,homeWallpaper:'<invalid>'}),n());
assert.deepEqual(n({homeLayout:'minimal',homeClock:'analogue',homeWallpaper:'ocean'}),{homeLayout:'minimal',homeClock:'analogue',homeWallpaper:'ocean'});
assert.deepEqual(n(JSON.parse(JSON.stringify(n({homeLayout:'split',homeClock:'blocks',homeWallpaper:'solid'})))),{homeLayout:'split',homeClock:'blocks',homeWallpaper:'solid'});
assert.deepEqual(c(0,0),{hour:'00',minute:'00',hourAngle:0,minuteAngle:0});
assert.deepEqual(c(15,30),{hour:'15',minute:'30',hourAngle:105,minuteAngle:180});
assert.deepEqual(c(23,59),{hour:'23',minute:'59',hourAngle:359.5,minuteAngle:354});
assert.equal(o.homeClock.length,4);assert.equal(o.homeWallpaper.length,5);assert.equal(o.homeLayout.length,3);
assert.ok(source.includes('Object.assign(prefs,normaliseHome(p))'));
assert.ok(source.includes('...normaliseHome(),autoHide:'));
assert.ok(source.includes("if(active==='home'&&k==='homeClock')renderHome()"));
assert.ok(source.includes('if(liveEnabled)renderLiveState()'));
assert.ok(css.includes('[data-home-layout=minimal] .tiles{display:none}'));
assert.ok(css.includes('[data-home-layout=split] #page'));
for(const id of ['ocean','dusk','forest','solid'])assert.ok(css.includes('[data-home-wallpaper='+id+']'));
assert.ok(css.includes('rotate(var(--hour-angle,0deg))'));
console.log('22 Home customization checks passed');
